function fieldKey(el){if(el.id)return '#'+el.id;if(el.name)return '[name="'+el.name.replace(/"/g,'')+'"]';if(!el.dataset.qeKey)el.dataset.qeKey='qe-'+uid();return '[data-qe-key="'+el.dataset.qeKey+'"]'}
