function applySnapshot(data){if(!data||!data.fields)return 0;if(data.workflow)S.workflow=data.workflow;if(data.reportNo)S.reportNo=data.reportNo;if(data.signature)S.signature=data.signature;if(data.stamp)S.stamp=data.stamp;if(data.store){try{if(data.store.draft)localStorage.setItem('qc_survey_draft_v2',data.store.draft);if(data.store.gnss)localStorage.setItem('qc_gnss_draft_v1',data.store.gnss);if(data.store.points)localStorage.setItem('qc_point_library_v221',data.store.points);if(data.store.inputHistory)localStorage.setItem('qc_input_history_v221',data.store.inputHistory)}catch(e){}}var n=0;Object.keys(data.fields).forEach(function(k){try{var el=document.querySelector(k);if(!el)return;if(el.type==='checkbox'||el.type==='radio')el.checked=!!data.fields[k];else el.value=data.fields[k];el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));n++}catch(e){}});save();audit('restore','snapshot','',n+' fields');return n}
/* Safe restore: current values win. Only empty fields and genuinely new structured rows/properties are added. */
function emptyValue(v){return v==null||v===false||String(v).trim()===''}
function mergeSafe(cur,inc,stats,path){if(inc==null)return cur;if(cur==null||cur===''||cur===false){stats.added++;return inc}if(Array.isArray(cur)&&Array.isArray(inc)){var out=cur.slice(),index={};out.forEach(function(x,i){var id=x&&typeof x==='object'&&(x.id||x.key||x.pointId||x.name);if(id!=null)index[String(id)]=i});inc.forEach(function(x){var id=x&&typeof x==='object'&&(x.id||x.key||x.pointId||x.name);if(id!=null&&index[String(id)]!=null)out[index[String(id)]]=mergeSafe(out[index[String(id)]],x,stats,path+'['+id+']');else{var sig;try{sig=JSON.stringify(x)}catch(e){sig=String(x)}var exists=out.some(function(y){try{return JSON.stringify(y)===sig}catch(e){return y===x}});if(!exists){out.push(x);stats.added++}}});return out}if(cur&&inc&&typeof cur==='object'&&typeof inc==='object'&&!Array.isArray(cur)&&!Array.isArray(inc)){var obj=Object.assign({},cur);Object.keys(inc).forEach(function(k){obj[k]=mergeSafe(cur[k],inc[k],stats,path+'.'+k)});return obj}if(String(cur)===String(inc)){stats.same++;return cur}stats.conflicts++;if(stats.conflictList.length<40)stats.conflictList.push(path);return cur}
function safePlan(data){var plan={added:[],same:0,conflicts:[],missing:0,stores:[]};Object.keys(data&&data.fields||{}).forEach(function(k){var el;try{el=document.querySelector(k)}catch(e){}if(!el){plan.missing++;return}var incoming=data.fields[k],current=(el.type==='checkbox'||el.type==='radio')?!!el.checked:el.value;if(emptyValue(current)&&!emptyValue(incoming))plan.added.push({key:k,el:el,value:incoming});else if(String(current)===String(incoming))plan.same++;else if(!emptyValue(incoming))plan.conflicts.push(k)});var map={draft:'qc_survey_draft_v2',gnss:'qc_gnss_draft_v1',points:'qc_point_library_v221',inputHistory:'qc_input_history_v221'};Object.keys(data&&data.store||{}).forEach(function(k){if(!data.store[k]||!map[k])return;try{var incoming=JSON.parse(data.store[k]),raw=localStorage.getItem(map[k]),current=raw?JSON.parse(raw):null,st={added:0,same:0,conflicts:0,conflictList:[]},merged=mergeSafe(current,incoming,st,k);plan.stores.push({key:map[k],value:JSON.stringify(merged),stats:st});plan.conflicts=plan.conflicts.concat(st.conflictList);for(var i=0;i<st.added;i++)plan.added.push({store:true})}catch(e){}});return plan}
function applySafePlan(data,plan){plan.stores.forEach(function(x){localStorage.setItem(x.key,x.value)});var count=0;plan.added.filter(function(x){return x.el}).forEach(function(x){var el=x.el;if(el.type==='checkbox'||el.type==='radio')el.checked=!!x.value;else el.value=x.value;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));if(window.QCFieldSource)QCFieldSource.mark(el,'restore');count++});if(!S.signature&&data.signature)S.signature=data.signature;if(!S.stamp&&data.stamp)S.stamp=data.stamp;save();audit('restore-safe','snapshot','','added '+plan.added.length+', preserved conflicts '+plan.conflicts.length,'current values kept');return count}
function safeRestorePreview(data,source){if(!data||!data.fields)throw Error('Invalid snapshot');var p=safePlan(data),ov=document.createElement('div');ov.className='modal-overlay';ov.style.zIndex='100500';ov.innerHTML='<div class="modal-card" style="max-width:720px"><h2>Safe Backup Restore · استرجاع آمن</h2><p class="qc-safe-restore-note">Current values are protected. Only empty fields and new non-conflicting rows will be added. Existing different values will not be replaced.<br>القيم الحالية محمية. ستُضاف الحقول الفارغة والصفوف الجديدة فقط، ولن تُستبدل القيم المختلفة.</p><div class="qc-safe-restore-summary"><div><b>'+p.added.length+'</b>New / جديد</div><div><b>'+p.conflicts.length+'</b>Protected conflicts / تعارض محمي</div><div><b>'+p.missing+'</b>Unavailable fields / غير ظاهر</div></div>'+(p.conflicts.length?'<details><summary>Protected current values · القيم التي ستبقى</summary><div class="qc-safe-conflicts">'+p.conflicts.slice(0,40).map(function(x){return '<div>'+esc(x)+'</div>'}).join('')+'</div></details>':'')+'<div class="modal-actions"><button class="btn" data-cancel>Cancel · إلغاء</button><button class="btn btn-primary" data-apply>Confirm safe add · تأكيد الإضافة الآمنة</button></div></div>';document.body.appendChild(ov);ov.querySelector('[data-cancel]').onclick=function(){ov.remove()};ov.querySelector('[data-apply]').onclick=function(){applySafePlan(data,p);ov.remove();toast('Safe restore added '+p.added.length+' items; '+p.conflicts.length+' current values preserved');setTimeout(function(){location.reload()},650)};audit('restore-preview',source||'backup','',p.added.length+' additions / '+p.conflicts.length+' protected conflicts');return p}
