async function parseSheet(f){if(!f)return[];var buf=await f.arrayBuffer(),rows=[];if(window.XLSX){var wb=XLSX.read(buf,{type:'array'}),sh=wb.Sheets[wb.SheetNames[0]];rows=XLSX.utils.sheet_to_json(sh,{defval:''})}else{var t=new TextDecoder().decode(buf),ls=t.split(/\r?\n/).filter(Boolean),h=ls.shift().split(/[,;\t]/);rows=ls.map(function(l){var o={},v=l.split(/[,;\t]/);h.forEach(function(k,i){o[k]=v[i]||''});return o})}return rows.map(normalizePoint).filter(function(x){return x.id||isFinite(x.e)||isFinite(x.n)})}
